// Name → portrait data URI ("" when there's no official sprite — the caller keeps its old art).
window.trainerArt = function (name) {
  const k = String(name || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  return (k && window.TRAINER_ART[k]) || "";
};
